export function getDict(lang: Lang) {
  const d = DICT[lang];
  return (key: string) => d[key] ?? DICT.fr[key] ?? key;
}

/** internal-link prefix for the active language ("" for fr, "/en" for en) */
export const langPrefix = (lang: Lang) => (lang === "en" ? "/en" : "");
